   {
    "f": "Pregnancy: folic acid?",
    "b": "5 mg/day, well before pregnancy ← ↓ neural tube defects"
   },
   {
    "f": "Breast feeding with AEDs?",
    "b": "Acceptable with nearly ALL"
   }
